// Generates CLAUDE.md from RULES.md + roles/claude.md.
// Run from the repository root: pnpm rules:sync
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const read = (p) => readFileSync(join(here, p), 'utf8').trim();

const header =
  '<!-- GENERATED from RULES.md + roles/claude.md by sync-rules.mjs. ' +
  'Do not edit this file: edit the sources and run "pnpm rules:sync". -->';
writeFileSync(join(here, 'CLAUDE.md'), `${header}\n\n${read('roles/claude.md')}\n\n${read('RULES.md')}\n`);
console.log('wrote CLAUDE.md');
